use vstd::prelude::*;

verus! {

    /// Given a vector `indices` of row‐indices and a 2D vector `choices` whose
    /// each row has exactly `indices.len()` elements, returns the “diagonal”
    /// picking `choices[indices[i]][i]` for each `i`.
    fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> (result: Vec<f64>)
        requires
            // each row of `choices` has length exactly `indices.len()`
            choices.iter().all(|row: &Vec<f64>| row.len() == indices.len()),
            // every index in `indices` is a valid row index into `choices`
            indices.iter().all(|&idx: &u8| (idx as usize) < choices.len()),
        ensures
            // length of the result matches the number of indices
            result.len() == indices.len(),
            // and for each position i, we picked choices[indices[i]][i]
            forall |i: nat| i < result.len() ==>
                result[i] == choices[indices[i] as usize][i],
    {
        // Pre‐allocate the result
        let mut result = Vec::with_capacity(indices.len());
        // We'll build it element by element
        let mut i: usize = 0;
        while i < indices.len()
            invariant
                // i never exceeds the length of indices
                i <= indices.len(),
                // we've already pushed exactly `i` elements
                result.len() == i,
                // and those first `i` elements satisfy the spec
                forall |j: nat| j < result.len() ==>
                    result[j] == choices[indices[j] as usize][j],
            decreases indices.len() - i,
        {
            let idx = indices[i];
            result.push(choices[idx as usize][i]);
            i += 1;
        }
        result
    }
}

